{"file_path": "/tmp/hspi_boot_test.py", "content": "#!/usr/bin/env python3
# HuangShan Pi (SF32LB52) boot + functional test driver.
# Follows README_zh-cn.md "自动化测试模式": RTS-to-RST reset, wait for NSH.
import serial, sys, time, select

PORT = "/dev/ttyUSB0"
BAUD = 1_000_000

def open_ser():
    s = serial.Serial(PORT, BAUD, timeout=0.3)
    s.reset_input_buffer()
    return s

def reset(s):
    s.rts = True;  time.sleep(0.08)
    s.rts = False; time.sleep(0.3)
    s.reset_input_buffer()

def read_until(s, marker, timeout=45.0, out=None):
    """Read until marker substring seen; return accumulated bytes decoded."""
    buf = b""
    t0 = time.time()
    while time.time() - t0 < timeout:
        chunk = s.read(4096)
        if chunk:
            buf += chunk
            if out is not None:
                out.write(chunk.decode(errors="replace"))
                out.flush()
            if marker.encode() in buf:
                return buf.decode(errors="replace")
        else:
            # small idle wait, keep CPU low
            time.sleep(0.05)
    if out is not None:
        out.write(buf.decode(errors="replace")); out.flush()
    return buf.decode(errors="replace")

def run_cmd(s, cmd, marker="nsh> ", timeout=20.0, out=None):
    s.write((cmd + "\n").encode())
    return read_until(s, marker, timeout=timeout, out=out)

def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "boot"
    with open_ser() as s:
        if mode in ("boot", "full"):
            reset(s)
            print("== waiting for NSH prompt ==")
            r = read_until(s, "nsh> ", timeout=90)
            if "nsh> " not in r:
                print("!! NO NSH PROMPT. Last output above. Boot FAILED.")
                return 1
            print("== NSH prompt reached ==")
        cmds = {
            "boot": ["uname -a", "ls /dev"],
            "full": ["uname -a", "ls /dev", "free", "ps", "help",
                     "adc -n 1", "date", "i2c dev 0x10 0x77", "i2c dev 0x40 0x4f",
                     "fb", "echo MARK-END"],
        }[mode]
        for c in cmds:
            print(f"\n######## $ {c} ########")
            run_cmd(s, c, out=sys.stdout)
    return 0

if __name__ == "__main__":
    sys.exit(main())
"}

