{"command": "cat > /tmp/retry_boot.py <<'EOF'
import serial, time, sys
s = serial.Serial("/dev/ttyUSB0", 1_000_000, timeout=0.2)
s.rts=False; s.dtr=False
MAX_ATTEMPTS=30
try:
    for n in range(1, MAX_ATTEMPTS+1):
        s.rts=True; time.sleep(0.12); s.rts=False
        t0=time.time(); buf=b""; quiet=0.0
        print(f"[{time.strftime('%H:%M:%S')}] attempt {n} ...", flush=True)
        ok=False
        while time.time()-t0 < 20:
            c=s.read(4096)
            if c:
                buf+=c; quiet=0.0
                sys.stdout.write(c.decode(errors='replace')); sys.stdout.flush()
                if b"nsh>" in buf or b"NuttShell" in buf:
                    ok=True; break
            else:
                time.sleep(0.5); quiet+=0.5
                if len(buf) >= 6 and quiet >= 3.0:
                    break
        if ok:
            print(f"\n>>> BOOT_OK on attempt {n} <<<", flush=True)
            break
        print(f"[{time.strftime('%H:%M:%S')}] attempt {n} done ({len(buf)} bytes)", flush=True)
        if n < MAX_ATTEMPTS:
            time.sleep(2)
finally:
    s.close()
EOF
